def decode_string(s: str) -> str:
    stack = []
    i = 0
    while i < len(s):
        if s[i] == '[':
            count = 1
            j = i + 1
            while j < len(s) and s[j] not in [']', ',']:
                if s[j] == '[':
                    count += 1
                elif s[j] == ',':
                    count *= int(s[j + 1 : j + len(str(count)) + 1])
                j += 1
            stack.append((count, s[i + 1 : j]))
            i = j
        else:
            count, sub_str = stack.pop()
            result = result + sub_str * count if result else sub_str * count
            i += 1
    return result

