def replace_missing_values(data: List[List[Optional[float]]]) -> List[List[float]]:
    cleaned_data = []
    column_means = defaultdict(float)

    for sub_list in data:
        row = [value if value is not None else column_means[i] for i, value in enumerate(sub_list)]
        cleaned_data.append(row)

        for i, value in enumerate(row):
            if value is not None:
                column_means[i] = (column_means[i] * len(cleaned_data) + value) / (len(cleaned_data) + 1)
            elif column_means[i] == 0:
                column_means[i] = 0

    return cleaned_data

