def longest_contiguous_subarray(numbers):
    if not numbers:
        return (0, None)
    max_length = 0
    current_length = 0
    current_value = numbers[0]
    for i in range(1, len(numbers)):
        if numbers[i] == current_value:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1
            current_value = numbers[i]
    max_length = max(max_length, current_length)
    return max_length, current_value

