from collections import defaultdict, deque

def wordLadderLength(beginWord, endWord, wordList):
    wordSet = set(wordList)
    if not endWord in wordSet:
        return 0
    if beginWord == endWord:
        return 1

    graph = defaultdict(list)
    for word in wordSet:
        for i in range(len(word)):
            new_word = word[:i] + "*" + word[i+1:]
            for other_word in wordSet:
                if other_word != word and new_word == other_word[:i] + "*" + other_word[i+1:]:
                    graph[word].append(other_word)
                    graph[other_word].append(word)

    queue = deque([(beginWord, 2)])
    visited = set([beginWord])

    while queue:
        word, length = queue.popleft()
        for neighbor in graph[word]:
            if neighbor == endWord:
                return length
            if neighbor not in visited:
                queue.append((neighbor, length + 1))
                visited.add(neighbor)

    return 0

