def lengthOfLongestSubstring(word):
    if not word:
        return 0

    max_length = 0
    current_length = 0

    seen = set()

    for char in word:
        if char in seen:
            current_length = 0
            seen.clear()
        else:
            seen.add(char)
            current_length += 1
            max_length = max(max_length, current_length)

    return max_length

