from itertools import permutations

def find_words(s, words):
    # Create a set of permutations of the scrambled string
    perms = set(map(''.join, permutations(s)))

    # Filter the permutations that are in the dictionary
    result = set()
    for word in words:
        if word in perms:
            result.add(word)

    return result

def is_visible(heights):
    visible = [True] * len(heights)
    for i in range(len(heights)):
        for j in range(i, len(heights)):
            if heights[j] > heights[i]:
                visible[i] = False
                break
    return visible

