def min_sessions(tasks, session_time):
    tasks.sort(reverse=True)
    sessions = 0
    current_sum = 0

    for task in tasks:
        if current_sum + task > session_time:
            sessions += 1
            current_sum = task
        else:
            current_sum += task

    if current_sum != 0:
        sessions += 1

    return sessions

